INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('995d2b5f-1b4c-4a45-a32b-4454c650afc2', '0b8ddab7-b106-4873-bc4d-3987421d265d', 5, 'O Encontro no Meio do Dia', NULL, '{"intro": "A rotina nos engole se n\u00e3o criarmos ilhas de sil\u00eancio.", "prayer": "Recite o Angelus ou uma ora\u00e7\u00e3o curta de entrega.", "practice": "Pare tudo por 2 minutos ao meio-dia para uma ora\u00e7\u00e3o r\u00e1pida.", "reflection": "Uma pausa para respirar \u00e9 uma pausa para lembrar de Deus.", "journal_prompt": "Voc\u00ea se lembrou dEle hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;